import psycopg2

conn = psycopg2.connect(
    dbname="hw2_db",
    user="postgres",
    password="postgres",
    host="127.0.0.1",
    port=5432
)

print("Підключення успішне!")

sql = """
SET TIME ZONE 'UTC';

DROP TABLE IF EXISTS
    hw2_customer_features_online,
    hw2_training_events,
    hw2_customer_features_offline,
    hw2_order_items,
    hw2_orders,
    hw2_products,
    hw2_customers
CASCADE;

CREATE TABLE hw2_customers (
    customer_id BIGINT PRIMARY KEY,
    signup_date DATE NOT NULL,
    country VARCHAR(100) NOT NULL,
    age INTEGER,
    customer_segment VARCHAR(50),
    CONSTRAINT hw2_customers_age_check
        CHECK (age IS NULL OR age >= 0)
);

CREATE TABLE hw2_products (
    product_id BIGINT PRIMARY KEY,
    product_name VARCHAR(200) NOT NULL,
    category VARCHAR(100) NOT NULL,
    price NUMERIC(12, 2) NOT NULL,
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT hw2_products_price_check CHECK (price >= 0)
);

CREATE TABLE hw2_orders (
    order_id BIGINT PRIMARY KEY,
    customer_id BIGINT NOT NULL
        REFERENCES hw2_customers(customer_id),
    order_date TIMESTAMPTZ NOT NULL,
    status VARCHAR(20) NOT NULL,
    total_amount NUMERIC(12, 2) NOT NULL,
    CONSTRAINT hw2_orders_status_check
        CHECK (status IN (
            'pending', 'paid', 'shipped', 'completed', 'cancelled'
        )),
    CONSTRAINT hw2_orders_total_check CHECK (total_amount >= 0)
);

CREATE TABLE hw2_order_items (
    order_id BIGINT NOT NULL
        REFERENCES hw2_orders(order_id) ON DELETE CASCADE,
    product_id BIGINT NOT NULL
        REFERENCES hw2_products(product_id),
    quantity INTEGER NOT NULL,
    unit_price NUMERIC(12, 2) NOT NULL,
    PRIMARY KEY (order_id, product_id),
    CONSTRAINT hw2_order_items_quantity_check CHECK (quantity > 0),
    CONSTRAINT hw2_order_items_price_check CHECK (unit_price >= 0)
);

CREATE TABLE hw2_customer_features_offline (
    customer_id BIGINT NOT NULL
        REFERENCES hw2_customers(customer_id),
    orders_30d INTEGER NOT NULL,
    avg_order_value NUMERIC(12, 2),
    total_spend_90d NUMERIC(12, 2),
    customer_segment VARCHAR(50),
    valid_from TIMESTAMPTZ NOT NULL,
    valid_to TIMESTAMPTZ,
    PRIMARY KEY (customer_id, valid_from),
    CONSTRAINT hw2_offline_orders_check CHECK (orders_30d >= 0),
    CONSTRAINT hw2_offline_avg_check
        CHECK (avg_order_value IS NULL OR avg_order_value >= 0),
    CONSTRAINT hw2_offline_spend_check
        CHECK (total_spend_90d IS NULL OR total_spend_90d >= 0),
    CONSTRAINT hw2_offline_validity_check
        CHECK (valid_to IS NULL OR valid_to > valid_from)
);

CREATE TABLE hw2_training_events (
    event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id BIGINT NOT NULL
        REFERENCES hw2_customers(customer_id),
    prediction_ts TIMESTAMPTZ NOT NULL,
    label_horizon_end TIMESTAMPTZ NOT NULL,
    repeat_purchase BOOLEAN NOT NULL,
    CONSTRAINT hw2_training_horizon_check
        CHECK (label_horizon_end > prediction_ts)
);

CREATE TABLE hw2_customer_features_online (
    customer_id BIGINT PRIMARY KEY
        REFERENCES hw2_customers(customer_id),
    orders_30d INTEGER NOT NULL,
    avg_order_value NUMERIC(12, 2),
    total_spend_90d NUMERIC(12, 2),
    customer_segment VARCHAR(50),
    feature_ts TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT hw2_online_orders_check CHECK (orders_30d >= 0),
    CONSTRAINT hw2_online_avg_check
        CHECK (avg_order_value IS NULL OR avg_order_value >= 0),
    CONSTRAINT hw2_online_spend_check
        CHECK (total_spend_90d IS NULL OR total_spend_90d >= 0)
);

CREATE INDEX hw2_idx_orders_customer
    ON hw2_orders(customer_id, order_date DESC);

CREATE INDEX hw2_idx_customer_features_asof
    ON hw2_customer_features_offline(customer_id, valid_from DESC);

CREATE INDEX hw2_idx_training_events_customer
    ON hw2_training_events(customer_id, prediction_ts);
"""

cur = conn.cursor()
cur.execute(sql)
conn.commit()
cur.close()

print("DDL виконано успішно. Створено 7 таблиць та 3 індекси.")

