# 1. Шукаємо інтервали, які перетинаються в одного клієнта
cur.execute("""
SELECT
    a.customer_id,
    a.valid_from AS first_from,
    a.valid_to AS first_to,
    b.valid_from AS second_from,
    b.valid_to AS second_to
FROM hw2_customer_features_offline a
JOIN hw2_customer_features_offline b
  ON a.customer_id = b.customer_id
 AND a.valid_from < b.valid_from
 AND a.valid_from < COALESCE(b.valid_to, 'infinity'::timestamptz)
 AND b.valid_from < COALESCE(a.valid_to, 'infinity'::timestamptz);
""")

overlaps = cur.fetchall()
print("Інтервали, що перетинаються:", len(overlaps))

for row in overlaps:
    print(row)


# 2. Перевіряємо кількість історичних записів і версій
cur.execute("""
SELECT
    COUNT(*) AS total_history_rows,
    COUNT(DISTINCT customer_id) AS customers,
    MIN(versions) AS min_versions,
    MAX(versions) AS max_versions
FROM (
    SELECT customer_id, COUNT(*) AS versions
    FROM hw2_customer_features_offline
    GROUP BY customer_id
) AS history_summary
CROSS JOIN (
    SELECT COUNT(*) AS total_rows
    FROM hw2_customer_features_offline
) AS totals;
""")

print("Перевірка кількості:", cur.fetchone())

cur.close()

